create table applicant_consents (status tinyint not null, applicant_id bigint not null, id bigint not null auto_increment, revoked_at datetime(6), signed_at datetime(6) not null, storage_url varchar(255), terms_version varchar(255), consent_type enum ('CONTACT','DATA_PROCESSING','MARKETING','MEDICAL','TERMS_AND_CONDITIONS','TRAVEL') not null, source enum ('OFFICE','PHONE','RECRUITMENT_DRIVE','WEBSITE'), primary key (id)) engine=InnoDB;
