create table applicant_media (applicant_id bigint not null, file_asset_id bigint not null, id bigint not null auto_increment, uploaded_at datetime(6) not null, description TEXT, media_type enum ('AUDIO','OTHER','PHOTO','VIDEO') not null, primary key (id)) engine=InnoDB;
create table applicant_profiles (available_from date, number_of_children integer, preferred_salary decimal(38,2), willing_to_relocate bit not null, years_of_experience integer, applicant_id bigint not null, created_at datetime(6), id bigint not null auto_increment, updated_at datetime(6), current_employer varchar(255), current_position varchar(255), education_level varchar(255), employment_status varchar(255), field_of_study varchar(255), languages TEXT, next_of_kin_name varchar(255), next_of_kin_phone varchar(255), next_of_kin_relationship varchar(255), preferred_countries TEXT, preferred_job_categories TEXT, preferred_salary_currency varchar(255), professional_summary TEXT, reason_for_leaving TEXT, relevant_experience TEXT, religion varchar(255), skills TEXT, availability enum ('AVAILABLE_IMMEDIATELY','AVAILABLE_IN_30_DAYS','EMPLOYED','UNAVAILABLE'), marital_status enum ('DIVORCED','MARRIED','SINGLE','WIDOWED'), primary key (id)) engine=InnoDB;
